  "requirement_definitions": [
    {
      "id": "DMSR-5053",
      "title": "Older Release Behavior",
      "text": "Apart from the ﬂexibility provided by requirements DMSR-1159, DMS-REQ0366, DMSR-1519, and DMSR-1368, the qualitative behavior of the data access services on the “older Data Releases” deﬁned in DMSR-5792 shall match that for the most recent nDRMin Data Releases."
    },
    {
      "id": "DMSR-3112",
      "title": "Query Availability",
      "text": "(Goal) A query (e.g., in ADQL) written against a particular Data Release SHOULD continue to be executable against the original Data Release for as long as it is available in the system, with few, if any, modiﬁcations."
    },
    {
      "id": "DMSR-4837",
      "title": "Data Management Unscheduled Downtime",
      "text": "The Data Management subsystem shall be designed to facilitate unplanned repair activities expected not to exceed DMDowntime days per year."
    },
    {
      "id": "DMSR-4245",
      "title": "Optimization of Cost, Reliability and Availability in Order",
      "text": "Within a ﬁxed cost envelope for the Data Management subsystem, the allocation of processing and storage facilities will optimize reliability over availability to end users."
    },
    {
      "id": "DMSR-6707",
      "title": "Compute Platform Heterogeneity",
      "text": "At any given LSST computational facility the DMS shall be capable of operations on a heterogeneous cluster of machines. The hardware, operating system, and other machine parameters shall be limited to a project-approved set."
    },
    {
      "id": "DMSR-7084",
      "title": "Pipeline Throughput",
      "text": "The infrastructure will be sized such that the net throughput of the data processing pipelines will permit a complete processing of a night’s observing data prior to the start of the next observing night, assuming no system outages."
    },
    {
      "id": "DMSR-4419",
      "title": "Pipeline Availability",
      "text": "Except in cases of major disaster, the DMS shall have no unscheduled outages of the DMS pipelines extending over a period greater than productionMaxDowntime. A major disaster is deﬁned as a natural disaster or act of war (e.g. ﬂood, ﬁre, hostile acts) that compromises or threatens to compromise the health and integrity of the DMS physical facility, computing equipment, or operational personnel."
    }
  ],
